const inp = $('When called by parent').first().json || {};
const cfg = $('Config').first().json || {};
const raw = String(inp.phone == null ? '' : inp.phone).trim();
let compact = raw.replace(/[\s\-().]/g, '');
if (compact.startsWith('00')) compact = '+' + compact.slice(2);
const phoneValid = /^\+[1-9]\d{7,14}$/.test(compact);
const digits = phoneValid ? compact.slice(1) : '';
const templateName = String(inp.template_name == null ? '' : inp.template_name).trim();
const language = String(inp.language == null ? '' : inp.language).trim();
const category = String(inp.category == null ? '' : inp.category).trim();
const variablesRaw = inp.variables_json == null ? '' : String(inp.variables_json).trim();
const processedRaw = inp.processed_params_json == null ? '' : String(inp.processed_params_json).trim();

function parseObj(rawText) {
  if (!rawText) return { ok: true, value: null };
  try {
    const v = JSON.parse(rawText);
    if (!v || typeof v !== 'object' || Array.isArray(v)) return { ok: false, value: null };
    return { ok: true, value: v };
  } catch (e) {
    return { ok: false, value: null };
  }
}

const processed = parseObj(processedRaw);
const variables = parseObj(variablesRaw);
let reason = null;
if (!phoneValid) reason = 'invalid_phone';
else if (!templateName || !language) reason = 'invalid_template';
else if (processedRaw && !processed.ok) reason = 'invalid_processed_params';
else if (!processedRaw && variablesRaw && !variables.ok) reason = 'invalid_variables';

return [{ json: {
  raw,
  phone: phoneValid ? compact : null,
  digits,
  ready: !reason,
  reason,
  template_name: templateName,
  language,
  category,
  variables: variables.ok ? variables.value : null,
  processed_params: processed.ok ? processed.value : null,
  base_url: String(cfg.base_url || '').replace(/\/+$/, ''),
  account_id: String(cfg.account_id || '').trim(),
  whatsapp_inbox_id: String(cfg.whatsapp_inbox_id || '').trim()
} }];

const n = $('Normalize input').first().json;
const out = {
  ok: false,
  reason: n.reason,
  phone: n.reason === 'invalid_phone' ? (n.raw || null) : n.phone
};
if (n.reason !== 'invalid_phone') {
  out.template_name = n.template_name || null;
  out.language = n.language || null;
}
return [{ json: out }];

const norm = $('Normalize input').first().json;
const body = $input.first().json || {};
const payload = Array.isArray(body.payload) ? body.payload : (Array.isArray(body) ? body : []);
const want = norm.digits;
function digitsOf(v) {
  return String(v == null ? '' : v).replace(/\D/g, '');
}
const matches = payload.filter((c) => c && digitsOf(c.phone_number) === want);
const inboxId = Number(norm.whatsapp_inbox_id);
if (matches.length !== 1) {
  return [{ json: {
    phone: norm.phone,
    digits: want,
    base_url: norm.base_url,
    account_id: norm.account_id,
    inbox_id: inboxId,
    match_count: matches.length,
    contact_id: null,
    contact_name: null,
    source_id: null
  } }];
}
const contact = matches[0];
const inboxes = Array.isArray(contact.contact_inboxes) ? contact.contact_inboxes : [];
const linked = inboxes.find((ci) => ci && ci.inbox && Number(ci.inbox.id) === inboxId);
return [{ json: {
  phone: norm.phone,
  digits: want,
  base_url: norm.base_url,
  account_id: norm.account_id,
  inbox_id: inboxId,
  match_count: 1,
  contact_id: contact.id,
  contact_name: contact.name || null,
  source_id: linked && linked.source_id ? String(linked.source_id) : null
} }];

const n = $('Normalize input').first().json;
const m = $('Exact digit match').first().json;
return [{ json: { ok: false, reason: 'ambiguous_phone', phone: n.phone, match_count: m.match_count } }];

const prev = $('Exact digit match').first().json;
const items = $input.all().map((it) => it.json || {});
let list = [];
if (items.length === 1 && Array.isArray(items[0].payload)) list = items[0].payload;
else list = items.filter((c) => c && (c.id !== undefined || c.inbox_id !== undefined));
const inboxId = Number(prev.inbox_id);
const mine = list.filter((c) => c && Number(c.inbox_id) === inboxId);
const rank = { open: 0, pending: 1, snoozed: 2, resolved: 3 };
function activity(c) {
  const v = c.last_activity_at != null ? c.last_activity_at : c.timestamp;
  if (typeof v === 'number') return v;
  const t = Date.parse(String(v || ''));
  return Number.isFinite(t) ? t : 0;
}
mine.sort((a, b) => {
  const ra = rank[String(a.status || '')];
  const rb = rank[String(b.status || '')];
  const da = ra === undefined ? 9 : ra;
  const db = rb === undefined ? 9 : rb;
  if (da !== db) return da - db;
  const ta = activity(a);
  const tb = activity(b);
  if (ta !== tb) return tb - ta;
  return Number(b.id || 0) - Number(a.id || 0);
});
const picked = mine[0] || null;
return [{ json: {
  phone: prev.phone,
  digits: prev.digits,
  contact_id: prev.contact_id,
  contact_name: prev.contact_name,
  inbox_id: prev.inbox_id,
  source_id: prev.source_id,
  conversation_id: picked ? picked.id : null,
  conversation_status: picked ? (picked.status || null) : null,
  has_conversation: !!picked,
  has_contact_inbox: !!prev.source_id
} }];

const p = $('Pick WhatsApp thread').first().json;
return [{ json: {
  phone: p.phone,
  contact_id: p.contact_id,
  contact_name: p.contact_name,
  inbox_id: p.inbox_id,
  source_id: p.source_id,
  conversation_id: p.conversation_id,
  conversation_status: p.conversation_status,
  created_conversation: false
} }];

const pick = $('Pick WhatsApp thread').first().json;
const body = $input.first().json || {};
const row = body.payload && !Array.isArray(body.payload) ? body.payload : body;
const source = row.source_id ? String(row.source_id) : String(pick.digits);
return [{ json: { source_id: source } }];

const pick = $('Pick WhatsApp thread').first().json;
const body = $input.first().json || {};
const convo = (body.payload && !Array.isArray(body.payload) && body.payload.id) ? body.payload : body;
let sourceId = pick.source_id || pick.digits;
if ($('Stamp source id').isExecuted()) {
  const stamped = $('Stamp source id').first().json.source_id;
  if (stamped) sourceId = stamped;
}
return [{ json: {
  phone: pick.phone,
  contact_id: pick.contact_id,
  contact_name: pick.contact_name,
  inbox_id: pick.inbox_id,
  source_id: sourceId,
  conversation_id: convo.id,
  conversation_status: convo.status || 'open',
  created_conversation: true
} }];

const norm = $('Normalize input').first().json;
const ctx = $('Prepare created').isExecuted()
  ? $('Prepare created').first().json
  : $('Prepare existing').first().json;

function stringifyMap(obj) {
  const out = {};
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return out;
  for (const key of Object.keys(obj)) {
    const v = obj[key];
    if (v === undefined || v === null) continue;
    out[String(key)] = String(v);
  }
  return out;
}

let processed;
if (norm.processed_params) {
  processed = JSON.parse(JSON.stringify(norm.processed_params));
  if (processed.body && typeof processed.body === 'object' && !Array.isArray(processed.body)) {
    processed.body = stringifyMap(processed.body);
  }
} else {
  processed = { body: stringifyMap(norm.variables || {}) };
}

const category = norm.category || 'UTILITY';
return [{ json: {
  phone: ctx.phone,
  contact_id: ctx.contact_id,
  conversation_id: ctx.conversation_id,
  created_conversation: ctx.created_conversation,
  content: norm.template_name,
  template_params: {
    name: norm.template_name,
    category,
    language: norm.language,
    processed_params: processed
  }
} }];

const built = $('Build template message').first().json;
const msg = $input.first().json || {};
const row = (msg.payload && !Array.isArray(msg.payload) && msg.payload.id) ? msg.payload : msg;
return [{ json: {
  ok: true,
  phone: built.phone,
  contact_id: built.contact_id,
  conversation_id: built.conversation_id,
  created_conversation: built.created_conversation,
  message_id: row.id == null ? null : row.id
} }];
